-- 0004_add_org_site — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- site: one row per SOP-DEL-02 "project/site" (E1 AC1, AC2). Staff see all rows; a client sees its own
-- rows marked visibility = 'client'; partners see nothing until a policy links rows to their assigned jobs.
CREATE TABLE site (
  id           uuid PRIMARY KEY,
  client_id    uuid NOT NULL REFERENCES client (id),
  -- CLIENT-CC-CITY-NNN (SOP-DEL-02 §3, D-18): unique and immutable (trigger below).
  project_id   text NOT NULL UNIQUE,
  country_code text NOT NULL CHECK (country_code ~ '^[A-Z]{2}$'),
  city_code    text NOT NULL CHECK (city_code ~ '^[A-Z]{3}$'),
  city_name    text NOT NULL,
  running_no   integer NOT NULL CHECK (running_no BETWEEN 1 AND 999),
  name         text NOT NULL,
  standard     text NOT NULL CHECK (standard IN ('L', 'S')),
  visibility   text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal', 'client')),
  created_at   timestamptz NOT NULL DEFAULT now(),
  archived_at  timestamptz,
  UNIQUE (client_id, city_code, running_no)
);
CREATE INDEX site_client ON site (client_id);

CREATE FUNCTION app.site_project_id_immutable() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'site.project_id is immutable (SOP-DEL-02 §3, D-18)';
END
$$;
CREATE TRIGGER site_project_id_immutable BEFORE UPDATE OF project_id, client_id, city_code, running_no ON site
  FOR EACH ROW WHEN (OLD.project_id IS DISTINCT FROM NEW.project_id
                     OR OLD.client_id IS DISTINCT FROM NEW.client_id
                     OR OLD.city_code IS DISTINCT FROM NEW.city_code
                     OR OLD.running_no IS DISTINCT FROM NEW.running_no)
  EXECUTE FUNCTION app.site_project_id_immutable();

ALTER TABLE site ENABLE ROW LEVEL SECURITY;
CREATE POLICY site_internal ON site FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY site_client_read ON site FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND visibility = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON site TO ocs_app;
